/**
 * The dtc_answers tool: a report, a roadmap idea or a release answers file to the normalised answers
 * the model reads. Every string taken from a record is cleaned and capped (`sanitise.ts`), lists
 * are capped, and the result is handed over as quoted data (`answersText`). Pure.
 */

import { hasTraversal } from './guard'
import { ideaReply, releaseVerdicts } from './records'
import { decisionsOf, hasReportShape, isFinal, isValidCompletion, itemsOf, parseJson } from './reports'
import type { RequestRef } from './paths'
import { dtcUrl } from './paths'
import { RESULT_MAX, clean, cleanLine, quoteData } from './sanitise'

type Json = Record<string, unknown>

/** The most entries kept of any one list in a record (items, quotes, marks, verdicts and the rest). */
export const LIST_MAX = 200
/** The most screenshot paths given for one release verdict. */
export const SHOTS_MAX = 20

/** A long field: the reviewer's words, cleaned and capped. */
const str = (v: unknown): string => clean(v)
/** A short field: an id, a title, a name. */
const label = (v: unknown, max?: number): string => cleanLine(v, max)
const count = (v: unknown): number => (Array.isArray(v) ? v.length : 0)
const list = (v: unknown): Json[] => (Array.isArray(v) ? v.filter((x): x is Json => x !== null && typeof x === 'object' && !Array.isArray(x)).slice(0, LIST_MAX) : [])

const STATUSES = ['pass', 'partial', 'fail', 'skip']
const PICTURE_SEGMENT = /^[A-Za-z0-9_-][A-Za-z0-9._ -]*$/

/**
 * A picture name as a report gives it, kept only when it is a plain relative path (at most four
 * segments of letters, digits, `.`, `_`, `-` and spaces; no `..`, no leading `/` or `~`): it names
 * a file beside the record, inside the records folder. Anything else reads as `''`.
 */
export function pictureName(v: unknown): string {
  if (typeof v !== 'string' || v === '' || v.length > 300 || hasTraversal(v)) return ''
  const parts = v.split('/')
  return parts.length <= 4 && parts.every(part => PICTURE_SEGMENT.test(part)) ? v : ''
}

/** One mark the reviewer drew on a picture: its number, its shape and exactly what was typed (may be empty). */
export type Mark = { n: number | null; shape: string; text: string }

/** One picture the reviewer marked up. */
export type Markup = {
  /** The original picture, as the report names it. */
  picture: string
  /** The copy with the shapes drawn in, as the report names it. */
  marked: string
  /** Where the words sit on the marked copy: `picture` (labels joined to the marks) or `list` (numbered pins; also what a record without the field has). */
  notes: 'picture' | 'list'
  /** On a decision: the option whose picture this is. Absent elsewhere. */
  option?: string
  marks: Mark[]
  /** How many of `picture` and `marked` were left out because the name is not a plain relative path. Absent when none. */
  namesWithheld?: number
}

/** The markups on an item, a decision or an observation, with every mark's words. */
export function markupsOf(holder: Json): Markup[] {
  return list(holder.markups).map(m => {
    const picture = pictureName(m.picture)
    const marked = pictureName(m.marked)
    const withheld = [[m.picture, picture], [m.marked, marked]].filter(([given, kept]) => typeof given === 'string' && given !== '' && kept === '').length
    return {
      picture,
      marked,
      notes: m.notes === 'picture' ? ('picture' as const) : ('list' as const),
      ...(label(m.option) !== '' ? { option: label(m.option) } : {}),
      marks: list(m.marks).map(k => ({ n: typeof k.n === 'number' && Number.isFinite(k.n) ? k.n : null, shape: label(k.shape, 40), text: str(k.text) })),
      ...(withheld > 0 ? { namesWithheld: withheld } : {}),
    }
  })
}

export type NormalisedAnswers = {
  request: string
  link: string
  title: string
  completedAt: string
  isCollected: boolean
  mode: string
  items: Array<{
    id: string
    title: string
    status: string
    comment: string
    flagged: Array<{ expectedIndex: number | null; text: string; comment: string }>
    quotes: Array<{ text: string; comment: string }>
    screenshots: number
    markups: Markup[]
    decisions: Array<{ id: string; question: string; choice: string | null; comment: string; markups: Markup[] }>
  }>
  observations: Array<{ id: string; text: string; screenshots: number; markups: Markup[] }>
}

export type AnswersResult = { ok: true; answers: NormalisedAnswers } | { ok: false; message: string }

const nameOf = (ref: RequestRef): string => `${ref.project}/${ref.rel.replace(/\.md$/, '')}`

/**
 * Normalises a final report. Errors plainly when it is missing, malformed or not final. With
 * `when`, a `completedAt` in the future, or earlier than the request was filed, is not final.
 */
export function normaliseAnswers(ref: RequestRef, reportText: string | null, isCollected: boolean, when?: { now: number; filedAt?: number }): AnswersResult {
  const name = nameOf(ref)
  if (reportText === null) return { ok: false, message: `No report for ${name}: the reviewer has not opened or answered it yet.` }
  const report: Json | null = parseJson(reportText)
  if (report === null) return { ok: false, message: `The report for ${name} could not be read (malformed or half-written); try again shortly.` }
  if (isFinal(report) && !hasReportShape(report)) return { ok: false, message: `The report for ${name} could not be read: it is not in the shape Dev Traffic Control writes.` }
  if (!isFinal(report)) return { ok: false, message: `The report for ${name} is not final (no valid completedAt): the reviewer is still answering. Do not read partial answers unless the reviewer says so.` }
  if (when !== undefined && !isValidCompletion(report.completedAt, when.now, when.filedAt)) {
    return { ok: false, message: `The report for ${name} has a completedAt that is in the future or earlier than the request was filed, so it is not treated as final.` }
  }
  return {
    ok: true,
    answers: {
      request: name,
      link: dtcUrl(ref),
      title: label(report.title),
      completedAt: label(report.completedAt, 40),
      isCollected,
      mode: label(report.mode, 40),
      items: itemsOf(report).slice(0, LIST_MAX).map(item => ({
        id: label(item.id),
        title: label(item.title),
        status: typeof item.status === 'string' && STATUSES.includes(item.status) ? item.status : 'unanswered',
        comment: str(item.comment),
        flagged: list(item.flagged).map(f => ({ expectedIndex: typeof f.expectedIndex === 'number' ? f.expectedIndex : null, text: str(f.text), comment: str(f.comment) })),
        quotes: list(item.quotes).map(q => ({ text: str(q.text), comment: str(q.comment) })),
        screenshots: count(item.screenshots),
        markups: markupsOf(item),
        decisions: decisionsOf(item).slice(0, LIST_MAX).map(d => ({
          id: label(d.id),
          question: str(d.question),
          choice: str(d.choice) === '' ? null : str(d.choice),
          comment: str(d.comment),
          markups: markupsOf(d),
        })),
      })),
      observations: list(report.observations).map(o => ({ id: label(o.id), text: str(o.text), screenshots: count(o.screenshots), markups: markupsOf(o) })),
    },
  }
}

/** A feature request's waiting reply, as the model reads it. */
export type IdeaAnswer = {
  kind: 'feature-request'
  idea: string
  link: string
  title: string
  /** The reviewer entry's answer (its heading's last part); `''` when the heading gives none. */
  answer: string
  /** The reviewer's words under the heading. */
  note: string
  /** The entry's date as written; `''` when the heading gives none. */
  at: string
  /** The idea's current `fate`; `''` when unset or not one of the contract's values. */
  fate: string
  /** The release the idea is currently aimed at; `''` when unset. */
  candidate: string
}

export type IdeaResult = { ok: true; answers: IdeaAnswer } | { ok: false; message: string }

/** Normalises an idea file's waiting reviewer entry. Errors plainly when the file is missing, unreadable or has no entry waiting. */
export function normaliseIdea(ref: RequestRef, ideaText: string | null): IdeaResult {
  const name = nameOf(ref)
  if (ideaText === null) return { ok: false, message: `The idea file for ${name} is missing or could not be read (or is larger than the inbox reads).` }
  const reply = ideaReply(ideaText)
  if (reply === null) return { ok: false, message: `No reviewer entry is waiting on ${name}: the idea has no entries, or its last entry is the agent's.` }
  return {
    ok: true,
    answers: {
      kind: 'feature-request',
      idea: ref.rel.replace(/^roadmap\//, '').replace(/\.md$/, ''),
      link: dtcUrl(ref),
      title: label(reply.title),
      answer: label(reply.answer, 500),
      note: str(reply.note),
      at: label(reply.at, 40),
      fate: reply.fate,
      candidate: label(reply.candidate, 60),
    },
  }
}

/** Release verdicts, as the model reads them. */
export type VerdictAnswers = {
  kind: 'release-verdicts'
  release: string
  link: string
  app: string
  version: string
  /** The newest verdict's time, as written; `''` when no verdict carries one. */
  newestAt: string
  verdicts: Array<{
    id: string
    verdict: 'works' | 'off'
    comment: string
    at: string
    /** Absolute paths of the pictures attached to the verdict that lie inside the records folder. */
    screenshots: string[]
    /** Pictures the answers file names that were left out: a path that leaves the records folder, or no file there. */
    screenshotsWithheld: number
    removed?: true
  }>
}

export type VerdictResult = { ok: true; answers: VerdictAnswers; stamp: string | null } | { ok: false; message: string }

/**
 * The absolute path a verdict's picture names: relative to the project folder, as the contract
 * writes it. Null for an absolute path, one that spells traversal, or one with characters outside
 * `pictureName`'s; whether it is a regular file inside the records folder is the caller's check
 * (`pictureExists`).
 */
export function shotPath(root: string, project: string, shot: string): string | null {
  if (shot.startsWith('/') || shot.startsWith('~') || pictureName(shot) === '') return null
  return `${root}/${project}/${shot}`
}

/**
 * Normalises a release answers file. Errors plainly when it is missing or unreadable. A picture
 * path is given only when `shotPath` accepts it and `pictureExists` (the confined regular-file
 * check: inside the records folder, no symbolic link on the way) says so; at most `SHOTS_MAX` per verdict.
 */
export async function normaliseVerdicts(
  ref: RequestRef,
  answersText: string | null,
  root: string,
  pictureExists: (path: string) => Promise<boolean>,
): Promise<VerdictResult> {
  const name = nameOf(ref)
  if (answersText === null) return { ok: false, message: `No verdicts for ${name}: the reviewer has not answered any feature of this release yet (or the answers file is larger than the inbox reads).` }
  const v = releaseVerdicts(answersText)
  if (v === null) return { ok: false, message: `The answers file for ${name} could not be read (malformed or half-written); try again shortly.` }
  const verdicts: VerdictAnswers['verdicts'] = []
  for (const a of v.answers.slice(0, LIST_MAX)) {
    const screenshots: string[] = []
    for (const shot of a.screenshots.slice(0, SHOTS_MAX)) {
      const path = shotPath(root, ref.project, shot)
      if (path !== null && (await pictureExists(path).catch(() => false))) screenshots.push(path)
    }
    verdicts.push({
      id: label(a.id),
      verdict: a.verdict,
      comment: str(a.comment),
      at: label(a.at, 40),
      screenshots,
      screenshotsWithheld: a.screenshots.length - screenshots.length,
      ...(a.removed === true ? { removed: true as const } : {}),
    })
  }
  return {
    ok: true,
    stamp: v.stamp,
    answers: { kind: 'release-verdicts', release: name, link: dtcUrl(ref), app: label(v.app), version: label(v.release), newestAt: v.stamp ?? '', verdicts },
  }
}

/** Every string in a value cut again to `max` characters. */
function recap(value: unknown, max: number): unknown {
  if (typeof value === 'string') return clean(value, max)
  if (Array.isArray(value)) return value.map(v => recap(v, max))
  if (value !== null && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, recap(v, max)]))
  return value
}

const render = (value: unknown): string => quoteData(JSON.stringify(value, null, 2))

/** Keeps the leading entries of each top-level list that fit `budget` characters; says how many were left out. */
function trimLists(value: Record<string, unknown>, budget: number): Record<string, unknown> {
  const out: Record<string, unknown> = { ...value }
  const lists = Object.keys(value).filter(k => Array.isArray(value[k]))
  for (const k of lists) out[k] = []
  let used = render(out).length + 200
  const omitted: Record<string, number> = {}
  for (const k of lists) {
    const all = value[k] as unknown[]
    const kept: unknown[] = []
    for (const el of all) {
      const text = JSON.stringify(el, null, 2)
      // Nested two levels down: four more spaces a line, a comma and a line end; marker look-alikes grow by one.
      const size = text.length + 4 * (text.split('\n').length + 1) + 2 + (text.match(/<<<|>>>/g)?.length ?? 0)
      if (used + size > budget) break
      used += size
      kept.push(el)
    }
    out[k] = kept
    if (kept.length < all.length) omitted[k] = all.length - kept.length
  }
  return Object.keys(omitted).length === 0 ? out : { ...out, omitted, omittedNote: 'Entries were left out to fit; the whole answer is in the record, in the Dev Traffic Control app.' }
}

/**
 * What `dtc_answers` returns: the fixed preamble, then the answers as JSON between the two marker
 * lines (`quoteData`), at most `RESULT_MAX` characters in all. An answer that would be longer has
 * every text field cut to 2,000 characters, then to 500, and then loses trailing list entries,
 * each step saying so inside the data.
 */
export function answersText(a: NormalisedAnswers | IdeaAnswer | VerdictAnswers): string {
  let value: Record<string, unknown> = a
  let text = render(value)
  for (const max of [2000, 500]) {
    if (text.length <= RESULT_MAX) return text
    value = { ...(recap(a, max) as Record<string, unknown>), cutNote: `Every text field was cut to ${max} characters to fit; the whole answer is in the record.` }
    text = render(value)
  }
  if (text.length <= RESULT_MAX) return text
  value = trimLists(value, RESULT_MAX)
  text = render(value)
  // The estimate above is close, not exact: drop one more entry at a time until it fits.
  while (text.length > RESULT_MAX) {
    const key = Object.keys(value).reverse().find(k => Array.isArray(value[k]) && (value[k] as unknown[]).length > 0)
    if (key === undefined) break
    value = { ...value, [key]: (value[key] as unknown[]).slice(0, -1) }
    text = render(value)
  }
  return text.length <= RESULT_MAX ? text : quoteData(JSON.stringify({ omittedNote: 'This answer is too large to hand over; read it in the Dev Traffic Control app.' }, null, 2))
}

files.hooks/bound-read.ts:
/**
 * The descriptor-bound read the host is asked for. The mods API reads files by pathname only, with
 * no no-follow open and no descriptor, so the open, the `fstat`, the read and the checks around
 * them run in one short helper process: the system's own Perl (core modules only), started with a
 * fixed program and the paths as plain arguments. The helper decides nothing: it reports what it
 * observed, in order, and `confinedTo` in `guard.ts` judges the facts. Where the helper cannot
 * run, there are no facts and every file read fails closed.
 */

import type { BoundFacts, BoundRequest } from './guard'

/** The one interpreter this is run with: an absolute path, never looked up on `PATH`. */
export const BOUND_READ_PROGRAM = '/usr/bin/perl'

/** First line of the helper's answer; anything else is not an answer. */
export const BOUND_READ_MARK = 'dtc-inbox-bound-read 2'

/** The most time one read may take before it counts as failed. */
export const BOUND_READ_TIMEOUT_MS = 5000

/**
 * The helper. Arguments: root, folder, leaf name, byte cap, `1` to read content or `0` to
 * identify only. It resolves the root and the folder, opens the leaf with `O_NOFOLLOW` (and
 * `O_NONBLOCK`, so a pipe or device never holds it), `fstat`s the descriptor, reads from the
 * descriptor only when that is a regular file with exactly one name (link count 1) within the cap
 * in a folder whose real path is under the root's, then resolves the root and the folder again and
 * `lstat`s the path. It prints nine lines; paths and content are base64. The fourth line carries
 * the opened file's kind, device, inode, size and link count. Content is printed only when the
 * read stayed within the cap.
 */
export const BOUND_READ_SCRIPT = `use strict; use warnings;
use Fcntl qw(O_RDONLY O_NOFOLLOW O_NONBLOCK S_ISREG S_ISDIR S_ISLNK);
use Cwd (); use MIME::Base64 ();
my ($root, $parent, $name, $max, $want) = @ARGV;
exit 2 unless @ARGV == 5 && $name ne '' && $name ne '.' && $name ne '..' && index($name, '/') < 0 && $max =~ /^[0-9]{1,10}$/ && $want =~ /^[01]$/;
sub b { return MIME::Base64::encode_base64(defined $_[0] ? $_[0] : '', '') }
sub kind { my $m = shift; return S_ISREG($m) ? 'file' : S_ISDIR($m) ? 'dir' : S_ISLNK($m) ? 'link' : 'other' }
my $r1 = Cwd::realpath($root); my $p1 = Cwd::realpath($parent);
exit 3 unless defined $r1 && defined $p1;
my $path = "$parent/$name";
sysopen(my $fh, $path, O_RDONLY | O_NOFOLLOW | O_NONBLOCK) or exit 4;
binmode($fh);
my @s = stat($fh); exit 5 unless @s;
my $k = kind($s[2]);
my ($data, $n) = ('', 0);
my $in = $p1 eq $r1 || index($p1, $r1 eq '/' ? '/' : "$r1/") == 0;
my $may = $want eq '1' && $in && $k eq 'file' && $s[3] == 1 && $s[7] <= $max;
if ($may) {
  while ($n <= $max) {
    my $got = sysread($fh, my $buf, 65536);
    exit 6 unless defined $got;
    last if $got == 0;
    $data .= $buf; $n += $got;
  }
}
my $r2 = Cwd::realpath($root); my $p2 = Cwd::realpath($parent);
my @l = lstat($path);
close($fh);
my $ok = $may && $n <= $max;
binmode(STDOUT);
print join("\\n", '${BOUND_READ_MARK}', b($r1), b($p1), "$k $s[0] $s[1] $s[7] $s[3]", "$n " . ($ok ? 1 : 0),
  (defined $r2 ? 'p ' . b($r2) : 'gone'), (defined $p2 ? 'p ' . b($p2) : 'gone'),
  (@l ? kind($l[2]) . " $l[0] $l[1]" : 'gone'), ($ok ? b($data) : '')), "\\n";
`

/** The argument list for one bound read: the program, the fixed script, then the request as plain arguments (no shell). */
export function boundReadArgv(req: BoundRequest): string[] {
  const cap = Number.isFinite(req.maxBytes) && req.maxBytes > 0 ? Math.floor(req.maxBytes) : 0
  return [BOUND_READ_PROGRAM, '-e', BOUND_READ_SCRIPT, '--', req.root, req.parent, req.name, String(cap), req.wantText ? '1' : '0']
}

const B64 = /^[A-Za-z0-9+/]*={0,2}$/

/** Base64 to the text of its UTF-8 bytes; null when it is not base64. */
function fromBase64(text: string): string | null {
  if (!B64.test(text) || text.length % 4 !== 0) return null
  try {
    const raw = atob(text)
    const bytes = new Uint8Array(raw.length)
    for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i)
    return new TextDecoder().decode(bytes)
  } catch {
    return null
  }
}

const KIND = ['file', 'dir', 'link', 'other'] as const
const isKind = (v: string | undefined): v is (typeof KIND)[number] => (KIND as readonly string[]).includes(v ?? '')
const isDigits = (v: string | undefined): v is string => v !== undefined && /^[0-9]{1,20}$/.test(v)

/** A resolved path as the helper prints it: `p <base64>`, or `gone`. `undefined` when the line is neither. */
function pathLine(line: string | undefined): string | null | undefined {
  if (line === 'gone') return null
  if (line === undefined || !line.startsWith('p ')) return undefined
  return fromBase64(line.slice(2)) ?? undefined
}

/** The helper's answer read as facts. Null for anything that is not exactly the nine lines it prints. */
export function parseBoundFacts(stdout: unknown): BoundFacts | null {
  if (typeof stdout !== 'string') return null
  const lines = stdout.split('\n')
  if (lines.length !== 10 || lines[9] !== '' || lines[0] !== BOUND_READ_MARK) return null
  const rootBefore = fromBase64(lines[1] as string)
  const parentBefore = fromBase64(lines[2] as string)
  if (rootBefore === null || parentBefore === null || rootBefore === '' || parentBefore === '') return null
  const [kind, dev, ino, size, nlink, ...restOpened] = (lines[3] as string).split(' ')
  if (restOpened.length > 0 || !isKind(kind) || kind === 'link' || !isDigits(dev) || !isDigits(ino) || !isDigits(size) || !isDigits(nlink)) return null
  const [count, hasText, ...restRead] = (lines[4] as string).split(' ')
  if (restRead.length > 0 || !isDigits(count) || (hasText !== '0' && hasText !== '1')) return null
  const rootAfter = pathLine(lines[5])
  const parentAfter = pathLine(lines[6])
  if (rootAfter === undefined || parentAfter === undefined) return null
  let leaf: BoundFacts['leaf'] = null
  if (lines[7] !== 'gone') {
    const [leafKind, leafDev, leafIno, ...restLeaf] = (lines[7] as string).split(' ')
    if (restLeaf.length > 0 || !isKind(leafKind) || !isDigits(leafDev) || !isDigits(leafIno)) return null
    leaf = { kind: leafKind, dev: leafDev, ino: leafIno }
  }
  let text: string | null = null
  if (hasText === '1') {
    text = fromBase64(lines[8] as string)
    if (text === null) return null
  } else if (lines[8] !== '') return null
  return { rootBefore, parentBefore, opened: { kind, dev, ino, size: Number(size), nlink: Number(nlink) }, bytes: Number(count), text, rootAfter, parentAfter, leaf }
}

/** What `$.process.run` answers with, as far as this reads it. */
export type RunResult = { exitCode?: unknown; stdout?: unknown; isStdoutTruncated?: unknown }

/**
 * A bound read through a process runner. Any failure is "no facts": the program is missing, it
 * exits non-zero (the open failed, a path did not resolve), its output was cut short or is not
 * the helper's.
 */
export function boundReadVia(run: (argv: string[], timeoutMs: number) => Promise<RunResult>): (req: BoundRequest) => Promise<BoundFacts | null> {
  return async req => {
    try {
      const out = await run(boundReadArgv(req), BOUND_READ_TIMEOUT_MS)
      if (out === null || typeof out !== 'object' || out.exitCode !== 0 || out.isStdoutTruncated === true) return null
      return parseBoundFacts(out.stdout)
    } catch {
      return null
    }
  }
}

files.hooks/config.ts:
import { expandHome, trimSlashes } from './paths'

export type Config = {
  /** The records folder. */
  root: string
  /** A folder whose sessions see every project's answers; `''` when not set. */
  hubDir: string
  bandMs: number
}

/** `root` is the app's own default records folder. `hubDir` has no default: unset, every session sees its own project only. */
export const DEFAULTS = { root: '~/Documents/Dev Traffic Control', hubDir: '', bandSeconds: 60 }

const seconds = (v: unknown, fallback: number): number => (typeof v === 'number' && Number.isFinite(v) && v >= 5 ? v : fallback)
const text = (v: unknown, fallback: string): string => (typeof v === 'string' && v.trim() !== '' ? v.trim() : fallback)

/** The plugin's options (`userConfig`) with defaults, `~` expanded. Options this version does not have are ignored. */
export function resolveConfig(options: Readonly<Record<string, unknown>>, home: string): Config {
  const hub = text(options.hubDir, DEFAULTS.hubDir)
  return {
    root: trimSlashes(expandHome(text(options.dtcRoot, DEFAULTS.root), home)),
    hubDir: hub === '' ? '' : trimSlashes(expandHome(hub, home)),
    bandMs: seconds(options.bandRefreshSeconds, DEFAULTS.bandSeconds) * 1000,
  }
}

files.hooks/guard.ts:
/**
 * The trust boundary. Everything that turns outside text (a tool argument, a dtc:// link, a
 * file name from the records folder, a path read back from the shared `$.store`) into a file read,
 * a process argument or prompt text passes through here. Pure except for the injected fs.
 */

import type { RequestRef } from './paths'

/** One path segment of a request: `[A-Za-z0-9._-]`, not starting with a dot (so never `.` or `..`). */
const SEGMENT = /^[A-Za-z0-9_-][A-Za-z0-9._-]*$/

export const isSafeSegment = (s: string): boolean => SEGMENT.test(s)

/**
 * The ref when it is safe to put into a prompt, a URL or a path: the project one safe
 * segment, `rel` one or two safe segments ending `.md`. Null otherwise.
 */
export function safeRef(ref: RequestRef): RequestRef | null {
  if (typeof ref.project !== 'string' || typeof ref.rel !== 'string') return null
  if (!isSafeSegment(ref.project)) return null
  const parts = ref.rel.split('/')
  if (parts.length < 1 || parts.length > 2 || !parts.every(isSafeSegment)) return null
  if (!ref.rel.endsWith('.md') || (parts[parts.length - 1] as string).length <= 3) return null
  return { project: ref.project, rel: ref.rel }
}

/**
 * Traversal or smuggling, spelt any way: a `.` or `..` segment, a control character (NUL
 * included), a backslash, or a percent-encoded dot, slash, backslash or NUL.
 */
export function hasTraversal(text: string): boolean {
  if (/[\u0000-\u001f\u007f\\]/.test(text)) return true
  if (/%(2e|2f|5c|00)/i.test(text)) return true
  return text.split('/').some(s => s === '..' || s === '.')
}

const trim = (p: string): string => (p.length > 1 ? p.replace(/\/+$/, '') : p)

/** `path` is `root` itself or below it, compared with a trailing separator (so `/x/records-evil` is not under `/x/records`). */
export function isWithin(path: string, root: string): boolean {
  const r = trim(root)
  return path === r || path.startsWith(r === '/' ? '/' : `${r}/`)
}

export type ConfineStat = { kind: 'file' | 'dir' | 'other'; realPath?: string; /** Bytes, for a file. */ size?: number; /** The path itself is a symbolic link. */ isLink?: boolean }

/** The most bytes read of any one file when the caller names no smaller cap. */
export const MAX_FILE_BYTES = 2 * 1024 * 1024

/** Which file a descriptor or a path names: device and inode, as decimal strings. */
export type FileId = { dev: string; ino: string }

/** What a descriptor-bound read is asked for: the leaf `name` in the folder `parent`, under `root`. */
export type BoundRequest = { root: string; parent: string; name: string; /** The most bytes of content to return. */ maxBytes: number; /** False: open and identify only, read no content. */ wantText: boolean }

/**
 * What one descriptor-bound read observed, in the order it happened. The host produces these
 * facts (see `bound-read.ts`); `confinedTo` judges them and nothing else decides a read.
 */
export type BoundFacts = {
  /** Real path of the root, resolved before the leaf was opened. */
  rootBefore: string
  /** Real path of the leaf's folder, resolved before the leaf was opened. */
  parentBefore: string
  /** `fstat` of the descriptor the leaf was opened to, without following a link at the leaf. `nlink` is how many names the file has. */
  opened: FileId & { kind: 'file' | 'dir' | 'other'; size: number; nlink: number }
  /** Bytes read from that descriptor; 0 when no content was asked for or none was read. */
  bytes: number
  /** The content read from that descriptor; null when none was asked for, or it was not a regular file, or it was over the cap. */
  text: string | null
  /** Real path of the root, resolved again after the read; null when it no longer resolves. */
  rootAfter: string | null
  /** Real path of the leaf's folder, resolved again after the read; null when it no longer resolves. */
  parentAfter: string | null
  /** `lstat` of the leaf's path after the read; null when nothing is there any more. */
  leaf: (FileId & { kind: 'file' | 'dir' | 'link' | 'other' }) | null
}

export type ConfineFs = {
  /** Resolved stat (`$.fs.stat(path, { resolve: true })`): null when the path is missing. Used for folders and presence only, never to read a file. */
  stat: (path: string) => Promise<ConfineStat | null>
  /**
   * The one way a file is opened: no-follow at the leaf, identified and read through the
   * descriptor, with the checks before and after reported as facts. Null when the open failed or
   * the facts could not be gathered. Absent when the host has no such call: every file read and
   * every file check then fails closed.
   */
  bound?: (req: BoundRequest) => Promise<BoundFacts | null>
}

export type Confined = {
  /**
   * Text of a regular file under the root that no symbolic link leads to, read from the descriptor
   * it was opened to (see `confinedTo`). Null otherwise, and null for a file larger than `maxBytes`
   * (default `MAX_FILE_BYTES`) or one that changed place or identity around the read.
   */
  read: (path: string, maxBytes?: number) => Promise<string | null>
  /** Whether the path is a regular file `read` would accept, whatever its size: the same open and the same checks, with no content read. */
  isFile: (path: string) => Promise<boolean>
  /** Whether the path exists and its real path is under the real root. Presence only: nothing is read. */
  exists: (path: string) => Promise<boolean>
  /** The real path of a directory at or under the root; null when it leaves the root or is not a directory. */
  dir: (path: string) => Promise<string | null>
}

const isId = (v: unknown): v is string => typeof v === 'string' && /^[0-9]+$/.test(v)

/**
 * Whether the facts of one bound read describe a regular file inside the root that stayed where
 * and what it was for the whole read. `expectedParent` is the root's real path plus the folder's
 * own spelling, so no folder between the root and the file may be a link. The file must have
 * exactly one name: a file with more (a hard link, which may name a file outside the root) is
 * refused. Any mismatch is a no.
 */
export function boundFactsHold(facts: BoundFacts | null | undefined, expectedParent: (rootReal: string) => string): facts is BoundFacts {
  if (facts === null || facts === undefined || typeof facts !== 'object') return false
  const root = facts.rootBefore
  if (typeof root !== 'string' || !root.startsWith('/') || facts.rootAfter !== root) return false
  const parent = expectedParent(trim(root))
  if (facts.parentBefore !== parent || facts.parentAfter !== parent) return false
  const o = facts.opened
  if (o === null || typeof o !== 'object' || o.kind !== 'file' || !isId(o.dev) || !isId(o.ino)) return false
  if (typeof o.size !== 'number' || !Number.isFinite(o.size) || o.size < 0) return false
  // A second name for the same file can lie anywhere on the disk: only a file with one name is read.
  if (o.nlink !== 1) return false
  const l = facts.leaf
  // The path must still name the very file the descriptor holds: not a link, not another file.
  return l !== null && typeof l === 'object' && l.kind === 'file' && l.dev === o.dev && l.ino === o.ino
}

/**
 * File access held to `root`. A path is refused when it spells traversal or its spelling is not
 * under the root. Every file is read through one primitive (`fs.bound`):
 *
 * 1. the real path of the file's folder must be the root's real path plus the folder's own
 *    spelling (inside the root, and no link on the way);
 * 2. the leaf is opened without following a link, and the descriptor is identified (`fstat`): a
 *    regular file with exactly one name (link count 1), no larger than the cap;
 * 3. the content is read from that descriptor, never from the pathname again;
 * 4. after the read the folder's real path must be unchanged, and the path must still name the
 *    same file (device and inode) as the descriptor.
 *
 * Anything else reads as "could not read": a mismatch, a host with no bound read, a failed call.
 * The root itself may be a link; its real path is resolved at every read and must not change
 * during it. A file with more than one name (a hard link) is "could not read", whichever name was asked for.
 */
export function confinedTo(root: string, fs: ConfineFs): Confined {
  const spelt = trim(root)
  const isSpeltInside = (path: string): boolean => typeof path === 'string' && path.startsWith('/') && !hasTraversal(path) && isWithin(path, spelt)
  let realRoot: Promise<string | null> | undefined
  const rootReal = (): Promise<string | null> =>
    (realRoot ??= fs
      .stat(spelt)
      .then(s => (s !== null && s.kind === 'dir' && typeof s.realPath === 'string' ? trim(s.realPath) : null))
      .catch(() => null))

  const place = async (path: string): Promise<(ConfineStat & { realPath: string }) | null> => {
    if (!isSpeltInside(path)) return null
    const r = await rootReal()
    if (r === null) return null
    const s = await fs.stat(path).catch(() => null)
    if (s === null || typeof s.realPath !== 'string' || !isWithin(s.realPath, r)) return null
    return { kind: s.kind, realPath: s.realPath, ...(typeof s.size === 'number' ? { size: s.size } : {}), ...(s.isLink === true ? { isLink: true } : {}) }
  }

  /** The facts of one bound read of `path`, when they hold; null otherwise. */
  const bound = async (path: string, maxBytes: number, wantText: boolean): Promise<BoundFacts | null> => {
    if (fs.bound === undefined || !isSpeltInside(path) || path === spelt) return null
    const cut = path.lastIndexOf('/')
    const parent = path.slice(0, cut)
    const name = path.slice(cut + 1)
    if (name === '' || !isWithin(parent, spelt)) return null
    const facts = await fs.bound({ root: spelt, parent, name, maxBytes, wantText }).catch(() => null)
    return boundFactsHold(facts, r => `${r === '/' ? '' : r}${parent.slice(spelt.length)}`) ? facts : null
  }

  return {
    read: async (path, maxBytes = MAX_FILE_BYTES) => {
      if (!Number.isFinite(maxBytes) || maxBytes < 0) return null
      const f = await bound(path, maxBytes, true)
      if (f === null || f.opened.size > maxBytes) return null
      if (typeof f.bytes !== 'number' || !Number.isFinite(f.bytes) || f.bytes > maxBytes) return null
      return typeof f.text !== 'string' || f.text.length > maxBytes ? null : f.text
    },
    isFile: async path => (await bound(path, 0, false)) !== null,
    exists: async path => (await place(path)) !== null,
    dir: async path => {
      const p = await place(path)
      return p !== null && p.kind === 'dir' ? p.realPath : null
    },
  }
}

/** Toast text: control characters (terminal escapes included) become spaces, at most `max` characters. */
export function plain(text: string, max = 200): string {
  const t = String(text).replace(/[\u0000-\u001f\u007f-\u009f\u061c\u200b-\u200f\u202a-\u202e\u2060-\u206f\ufeff]/g, ' ')
  return t.length > max ? `${t.slice(0, max - 1)}…` : t
}

files.hooks/filing.ts:
/**
 * Recording a filed request: this session's own note of it (`$.state`), the turn's written paths
 * and the shared registry (`$.store`). Each is read–modify–written under this load's lock, so
 * parallel Write hooks never lose a filing. I/O is injected.
 */

import { recordFiling, recordLocalFiling } from './inbox'
import type { LocalFilings, Registry, RegistryEntry } from './inbox'
import type { WithLock } from './lock'

export type FilingIo = {
  readLocal: () => Promise<LocalFilings>
  writeLocal: (v: LocalFilings) => Promise<void>
  /** The shared registry. Must reject when it cannot be read: an unread registry is never written back as an empty one. */
  readRegistry: () => Promise<Registry>
  writeRegistry: (v: Registry) => Promise<void>
  readWrites: () => Promise<string[]>
  writeWrites: (v: string[]) => Promise<void>
}

/**
 * Records one filing. The session-local note and the turn's written paths go first; then the
 * registry entry is replaced. When the registry cannot be read or written this rejects, with the
 * local note and the turn's paths kept: the record then shows no asking session in the pane.
 */
export async function recordRequestFiling(io: FilingIo, withLock: WithLock, entry: RegistryEntry): Promise<void> {
  await withLock(async () => io.writeLocal(recordLocalFiling(await io.readLocal(), entry.path, { project: entry.project, filedAt: entry.filedAt, lastAt: entry.filedAt })))
  await withLock(async () => {
    const held = await io.readWrites()
    await io.writeWrites([...held.filter(p => p !== entry.path), entry.path])
  })
  await withLock(async () => io.writeRegistry(recordFiling(await io.readRegistry(), entry)))
}

files.hooks/inbox.ts:
/** Who filed which record, the waiting set and the band count. Pure over what a scan returned and what the store holds. */

import type { Scope } from './paths'
import { whenMs } from './scan'
import type { ScanEntry } from './scan'

/**
 * A record (request, roadmap idea or release record) this mod saw an agent write. Shared across
 * sessions in `$.store`, and used for display only: the pane's "From this session" section and
 * the line saying which session asked. `filedAt` is the time of the latest write of the record.
 */
export type RegistryEntry = { path: string; sessionId: string; project: string; filedAt: number; /** The filing session's label at filing time. */ label?: string }
export type Registry = Record<string, RegistryEntry>

/**
 * The records this session itself filed, kept in its own `$.state` (no other session can write
 * it). Keyed by record path. `filedAt` is the first time this session wrote the record, `lastAt`
 * the latest. `dtc_answers` uses the first time to tell an answer given before the request was
 * filed from one given after.
 */
export type LocalFiling = { project: string; filedAt: number; lastAt?: number }
export type LocalFilings = Record<string, LocalFiling>

/** Records this session's filing; the first filing time is kept when the same record is written again, and the latest noted beside it. */
export function recordLocalFiling(local: LocalFilings, path: string, filing: LocalFiling): LocalFilings {
  const held = local[path]
  const lastAt = Math.max(held?.lastAt ?? held?.filedAt ?? filing.filedAt, filing.lastAt ?? filing.filedAt)
  return { ...local, [path]: { project: filing.project, filedAt: held === undefined ? filing.filedAt : Math.min(held.filedAt, filing.filedAt), lastAt } }
}

/** Records a filing; filing the same path again replaces the entry. */
export function recordFiling(registry: Registry, entry: RegistryEntry): Registry {
  return { ...registry, [entry.path]: entry }
}

export function inScope(entry: { project: string }, scope: Scope): boolean {
  return scope.kind === 'hub' || scope.project === entry.project
}

function newestFirst(a: ScanEntry, b: ScanEntry): number {
  return whenMs(b) - whenMs(a) || (a.rel < b.rel ? -1 : 1)
}

/** Answers waiting in scope (completed, uncollected reports; reviewer entries on ideas; release verdicts), newest first. */
export function waitingSet(entries: readonly ScanEntry[], scope: Scope): ScanEntry[] {
  return entries.filter(e => e.state === 'waiting' && inScope(e, scope)).sort(newestFirst)
}

/** Answer files in scope that could not be read (`state: 'malformed'`): listed, never counted or collected. */
export function unreadableSet(entries: readonly ScanEntry[], scope: Scope): ScanEntry[] {
  return entries.filter(e => e.state === 'malformed' && inScope(e, scope)).sort((a, b) => (a.rel < b.rel ? -1 : 1))
}

/** Opened, not finished: opened with no report, or a report with no `completedAt`. */
export function openedNotFinished(entries: readonly ScanEntry[], scope: Scope): ScanEntry[] {
  return entries.filter(e => (e.state === 'opened' || e.state === 'in-progress') && inScope(e, scope)).sort((a, b) => (a.rel < b.rel ? -1 : 1))
}

/** The band count: the answers waiting in scope. An answer leaves it when the agent writes its receipt. */
export function bandCount(entries: readonly ScanEntry[], scope: Scope): number {
  return waitingSet(entries, scope).length
}

